definition.script:
pipeline {
    agent any
    stages {

        stage('构建 Docker 镜像') {
            steps {
                script {
                    // 创建 Dockerfile
                    writeFile file: 'Dockerfile', text: "${DOCKERFILE_CONTENT}"

                    // 登录 Harbor 仓库
                    withCredentials([usernamePassword(
                        credentialsId: "${HARBOR_CREDENTIALS_ID}",
                        usernameVariable: 'HARBOR_USER',
                        passwordVariable: 'HARBOR_PASSWORD'
                    )]) {
                        sh """
                            sudo docker login -u $HARBOR_USER -p $HARBOR_PASSWORD ${HARBOR_URL}
                        """
                    }
                    def cleanHarborUrl = "${HARBOR_URL}"
                        .replaceFirst(/^https?:\/\//, '')  // 移除 http:// 或 https://


                    // 构建并推送镜像（支持多个标签）
                    def tags = "${DOCKER_IMAGE_TAGS}".split(',').collect { tag ->
                        "${cleanHarborUrl}/xnet-mlops-smp-python/${DOCKER_IMAGE_NAME}:${tag.trim()}"
                    }

                    tags.each { fullTag ->
                        sh """
                            sudo docker build -t $fullTag
                            sudo docker push $fullTag
                        """
                    }

                    // 清理本地镜像
                    tags.each { fullTag ->
                        sh "sudo docker rmi $fullTag || true"
                    }
                }
            }
        }
    }
}
